/** Messaging links for BroadNet SMS and OmniChannels batches, and conversions. */
export class Messaging {
  constructor(private readonly r: Requester) {}

  /**
   * List batches with funnel
   * `GET /messaging/batches` (permission: read)
   */
  readonly listBatches = (query?: ListMessagingBatchesQuery, options?: RequestOptions): Promise<any> =>
    this.r.request({ method: 'GET', path: '/messaging/batches', query }, options);

  /**
   * Issue messaging links
   * Create one unguessable short link per message sent through **BroadNet SMS & OmniChannels** (BroadNet is the exclusive provider). Retries are safe: the same `batch_ref` returns the same batch, and an `external_message_id` always keeps its link. Do not send phone numbers; `recipient_ref` is optional and stored only as an HMAC. When a person taps a link, the destination receives a signed click token (`?bn_cid=...` by default) for conversion attribution. Each link counts toward your plan's monthly links.
   * `POST /messaging/batches` (permission: write)
   */
  readonly createBatch = (body: {
    name?: string;
    destination: string;
    /** BroadNet SMS & OmniChannels (only provider) */
    provider?: "broadnet";
    channel?: "sms" | "whatsapp" | "rcs" | "viber" | "email" | "other";
    /** A verified custom domain (recipients see your brand in the link) */
    domain_id?: number;
    /** One of your sender IDs (GET /messaging/sender-ids). Its links go on its own domain, and in its long link mode each message's `url` is the destination with a signed `bn_m` tag. */
    sender_id?: number;
    /** 0 = never */
    link_expires_days?: number;
    /** Idempotency key for the whole batch */
    batch_ref?: string;
    recipients: Array<{
      /** BroadNet's message ID (used to match delivery reports) */
      external_message_id: string;
      /** Optional opaque reference (never a phone number) */
      recipient_ref?: string;
      /** Personalised destination on the same host as the batch destination */
      destination?: string;
    }>;
    /** Query parameter that carries the click token; null turns conversion tracking off */
    conversion_param?: string | null;
    /** Attribution window after the click (or after sending, for message-id conversions) */
    attribution_days?: number;
  }, options?: RequestOptions): Promise<any> =>
    this.r.request({ method: 'POST', path: '/messaging/batches', body }, options);

  /**
   * Batch report
   * Funnel (issued, delivered, previewed, clicked, click rate), statuses, top failure reasons, first clicks by hour and average time to first click. Click rate is per delivered message when receipts exist, otherwise per issued link (`ctr_basis`). Conversions: attributed (by click token or message id), unattributed (outside the window), revenue per currency, by event name, average time from click to conversion.
   * `GET /messaging/batches/{batch_id}` (permission: read)
   */
  readonly getBatch = (batchId: number, options?: RequestOptions): Promise<any> =>
    this.r.request({ method: 'GET', path: '/messaging/batches/{batch_id}', pathParams: { batch_id: batchId } }, options);

  /**
   * Per-message status
   * `GET /messaging/batches/{batch_id}/messages` (permission: read)
   */
  readonly listMessages = (batchId: number, query?: ListMessagingMessagesQuery, options?: RequestOptions): Promise<Page<any>> =>
    this.r.request({ method: 'GET', path: '/messaging/batches/{batch_id}/messages', pathParams: { batch_id: batchId }, query, paged: true }, options);

  /**
   * Report a conversion (server)
   * Attribute a purchase, lead or other conversion to a message. Send the `click_token` your landing page received (`bn_cid`), or `external_message_id` when no click is known (counted as message-attributed). Each `event_id` counts once; conversions outside the batch's attribution window are stored as unattributed.
   * `POST /messaging/conversions` (permission: write)
   */
  readonly recordConversion = (body: {
    click_token?: string;
    external_message_id?: string;
    event_id: string;
    event_name?: string;
    value?: number;
    currency?: string;
    /** Defaults to now; within the last 90 days */
    occurred_at?: string;
  }, options?: RequestOptions): Promise<any> =>
    this.r.request({ method: 'POST', path: '/messaging/conversions', body }, options);

  /**
   * List sender IDs
   * Your SMS sender IDs, each with its route country, own short domain and link mode.
   * `GET /messaging/sender-ids` (permission: read)
   */
  readonly listSenderIds = (options?: RequestOptions): Promise<Array<T.SenderId>> =>
    this.r.request({ method: 'GET', path: '/messaging/sender-ids' }, options);

  /**
   * Add a sender ID
   * A sender ID as registered with the carriers through BroadNet. Carriers control the sender ID only, not the links in a message. Optionally tie it to your own verified domain (its batches then put every link there); `link_mode: long` sends the destination itself with a signed tag instead of a short link. Promotional sender IDs need the route's marker: "AD-" prefix (UAE), "-AD" suffix (Saudi Arabia).
   * `POST /messaging/sender-ids` (permission: write)
   */
  readonly createSenderId = (body: T.SenderIdInput, options?: RequestOptions): Promise<T.SenderId> =>
    this.r.request({ method: 'POST', path: '/messaging/sender-ids', body }, options);

  /**
   * Get a sender ID
   * `GET /messaging/sender-ids/{sender_id}` (permission: read)
   */
  readonly getSenderId = (senderId: number, options?: RequestOptions): Promise<T.SenderId> =>
    this.r.request({ method: 'GET', path: '/messaging/sender-ids/{sender_id}', pathParams: { sender_id: senderId } }, options);

  /**
   * Update a sender ID
   * Change any field; the route's rules are checked again. PATCH works the same way.
   * `PUT /messaging/sender-ids/{sender_id}` (permission: write)
   */
  readonly updateSenderId = (senderId: number, body: T.SenderIdUpdate, options?: RequestOptions): Promise<T.SenderId> =>
    this.r.request({ method: 'PUT', path: '/messaging/sender-ids/{sender_id}', pathParams: { sender_id: senderId }, body }, options);

  /**
   * Update a sender ID (partial)
   * `PATCH /messaging/sender-ids/{sender_id}` (permission: write)
   */
  readonly patchSenderId = (senderId: number, body: T.SenderIdUpdate, options?: RequestOptions): Promise<T.SenderId> =>
    this.r.request({ method: 'PATCH', path: '/messaging/sender-ids/{sender_id}', pathParams: { sender_id: senderId }, body }, options);

  /**
   * Delete a sender ID
   * Existing batches and their links keep working.
   * `DELETE /messaging/sender-ids/{sender_id}` (permission: delete)
   */
  readonly deleteSenderId = (senderId: number, options?: RequestOptions): Promise<{
      deleted?: boolean;
      id?: number;
    }> =>
    this.r.request({ method: 'DELETE', path: '/messaging/sender-ids/{sender_id}', pathParams: { sender_id: senderId } }, options);

  /**
   * URLs a sender ID's messages carry
   * Every URL the messages of this sender ID carry: its short domain (every short link is https://<domain>/<9-character code>) and every destination its batches used, with first and last use. `format=csv` returns the same rows as a CSV file.
   * `GET /messaging/sender-ids/{sender_id}/url-pack` (permission: read)
   */
  readonly getSenderIdUrlPack = (senderId: number, query?: GetSenderIdUrlPackQuery, options?: RequestOptions): Promise<BinaryResult | any> =>
    this.r.request({ method: 'GET', path: '/messaging/sender-ids/{sender_id}/url-pack', pathParams: { sender_id: senderId }, query }, options);

}

/** conversions */
export class Conversions {
  constructor(private readonly r: Requester) {}

  /**
   * List Conversions
   * Conversions reported for the account's links, newest first, counted or not.
   * `GET /conversions` (permission: read)
   */
  readonly list = (query?: ListConversionsQuery, options?: RequestOptions): Promise<Page<T.Conversion>> =>
    this.r.request({ method: 'GET', path: '/conversions', query, paged: true }, options);

  /**
   * Report a Conversion
   * Report a purchase, sign-up, lead or other conversion from your server, with the click token (`bn_cid`) the visitor arrived with on a link that tracks conversions (`conversion_tracking`). It counts for that click when it happens within the account's attribution window (30 days unless changed); later ones are kept as `unattributed`. Each `event_id` counts once per account (200 with `duplicate: true` on a retry). Counted conversions send the `link.converted` webhook and go to the link's server-side pixels. Tokens of messaging links are recorded in the batch funnel (see POST /messaging/conversions).
   * `POST /conversions` (permission: write)
   */
  readonly create = (body: {
    /** The bn_cid parameter the visitor arrived with */
    click_token: string;
    /** Your unique id for this conversion, e.g. the order number */
    event_id: string;
    /** Lowercase, e.g. purchase, signup, lead */
    event_name?: string;
    value?: number;
    /** ISO 4217; USD when a value comes without one */
    currency?: string;
    /** Defaults to now; within the last 90 days */
    occurred_at?: string;
  }, options?: RequestOptions): Promise<T.ConversionResult> =>
    this.r.request({ method: 'POST', path: '/conversions', body }, options);

}

